    "seo": {
      "showcase3d": {
        "title": "LexiClash: A World of Words | Free Multiplayer Word Game",
        "description": "Scroll into a world of words: trace words on the board, chain combos, beat the room in real-time 1v3 battles, and take the crown. Free, browser-based, 6 languages. No download."
      },
      "stepLabel": "Step",
      "whatIsTitle": "What is LexiClash?",
      "whatIsContent": "LexiClash is a free, fast-paced multiplayer word game you can play right in your browser. Compete with friends in real-time word battles on a shared letter grid. Find words, build combos, and climb the leaderboard. It's like Boggle meets Wordle, but multiplayer. No downloads, no sign-ups required. Available in English, Hebrew, Swedish, Japanese, Spanish, and Russian.",
      "whatIsShort": "Free multiplayer word battles in your browser. Find words, build combos, crush your friends. No downloads, no signup.",
      "featuresTitle": "Why players love LexiClash",
      "feature1Title": "Real-time multiplayer",
      "feature1Desc": "Compete head-to-head with 2-20 players simultaneously. Create a room, share the code, and play instantly.",
      "feature2Title": "Daily Challenges",
      "feature2Desc": "Same puzzle for everyone worldwide, every day. Track your streak and share emoji results, just like Wordle.",
      "feature3Title": "Adventure Mode",
      "feature3Desc": "100 levels across 10 themed worlds. Special tiles, boss battles, and power-ups keep every round fresh.",
      "feature4Title": "6 languages",
      "feature4TitleShort": "Blast Mode",
      "feature4Desc": "Play in English, Hebrew, Swedish, Japanese, Spanish, or Russian. Switch anytime and challenge friends across languages.",
      "modeTagMultiplayer": "2-20 players",
      "modeTagDaily": "New puzzle daily",
      "modeTagAdventure": "100 levels",
      "modeTagBlast": "Chain reactions",
      "feature5Title": "Community Boards",
      "modeTagCommunity": "Player-made puzzles",
      "highlightMobile": "Any device, any browser",
      "highlightAges": "Ages 6+",
      "highlightEdu": "Used in classrooms",
      "highlightNoSignup": "No signup needed",
      "howToPlayTitle": "How to play",
      "step1": "Create or join a game room",
      "step2": "Swipe adjacent letters to form words",
      "step3": "Build combos for bonus points",
      "step4": "Score the most points to win",
      "blogTitle": "From our blog",
      "viewAllPosts": "View all posts →",
      "whoCanPlayTitle": "Who can play?",
      "whoCanPlayContent": "LexiClash is for everyone, from casual players after a fun break to competitive word game fans chasing the leaderboard. The game works on any device with a web browser: phones, tablets, laptops, and desktops. No app downloads, no sign-ups required to start playing. Players as young as 6 can enjoy the game, with child-safety features built in. Students building vocabulary, teachers running classroom word battles, and friends after a party game can all play at their own pace.",
      "gameModesTitle": "Game modes explained",
      "gameModesMultiplayer": "Multiplayer Rooms: create a private room and share the code with up to 20 friends. Everyone sees the same letter grid and races to find words before time runs out. The player with the highest score wins. Perfect for parties, classrooms, and remote team-building.",
      "gameModesSingle": "Single Player vs. Bots: practice your word-finding skills against AI opponents of varying difficulty. Set personal records, earn achievements, and sharpen your strategy without the pressure of live competition.",
      "gameModesDaily": "Daily Challenge: a fresh puzzle every day, identical for all players worldwide. Complete it to maintain your streak and compare your score with the global community. Share your results with emoji grids, just like Wordle.",
      "gameModesAdventure": "Adventure Mode: play through 10 themed worlds with 100 levels of increasing difficulty. Encounter special tile types like ice, fire, bombs, and rainbow tiles. Defeat bosses using word power and unlock new worlds as you progress.",
      "educationTitle": "Built for learning",
      "educationContent": "Word games are one of the most effective ways to build vocabulary and improve spelling. Research published in AIMS Neuroscience shows that word puzzles activate multiple brain regions simultaneously, including areas responsible for language processing, working memory, and executive function. LexiClash takes this further by offering gameplay in six languages, making it a practical tool for language learners. Teachers use LexiClash in classrooms across three continents to make vocabulary drills engaging. The multiplayer format creates healthy competition that motivates students to expand their word knowledge naturally.",
      "faqTitle": "Frequently Asked Questions",
      "faq1Q": "Is LexiClash really free?",
      "faq1A": "Yes, completely free. No hidden paywalls, no premium subscriptions. We sustain the game through non-intrusive advertising that respects your privacy.",
      "faq2Q": "Do I need to create an account?",
      "faq2A": "No. You can play as a guest instantly. Creating an account (via Google or Discord) unlocks features like leaderboard rankings, achievement tracking, and progress saving across devices.",
      "faq3Q": "What languages are supported?",
      "faq3A": "LexiClash supports English, Hebrew, Swedish, Japanese, Spanish, and Russian. Each language has its own curated dictionary, daily challenges, and leaderboards. You can switch languages anytime from the settings menu.",
      "faq4Q": "Can I play on my phone?",
      "faq4A": "Absolutely. LexiClash is fully responsive and works on any modern mobile browser. Swipe letters to form words. The touch controls are built for mobile play.",
      "faq5Q": "Is it safe for children?",
      "faq5A": "Yes. LexiClash is designed for players ages 6 and up. We comply with COPPA regulations, serve only non-personalized ads, and do not track children's browsing behavior.",
      "faq6Q": "Can I create my own board?",
      "faq6A": "Yes. Use the Community Board Builder to design custom letter grids with your own seed words. Publish them for others to play, rate, and compete on. Top boards get featured on the home page.",
      "communityTitle": "Word nerds welcome.",
      "communityContent": "LexiClash players span over 40 countries and six languages. Join the community to compete on global leaderboards, share daily challenge results, and discover new word strategies. Follow us on Instagram @lexi.clash for tips, updates, and community highlights."
    },
